import app from 'flarum/forum/app';
import Button from 'flarum/common/components/Button';
import Icon from 'flarum/common/components/Icon';
import Link from 'flarum/common/components/Link';
import { quizUrl } from '../../common/api';
import { percent } from '../../common/format';
const t = function (key, params) {
  if (params === void 0) {
    params = {};
  }
  return app.translator.trans(`ernestdefoe-gauntlet.forum.card.${key}`, params);
};

/** "Best: 80%" with a tick once passed; empty before the first attempt. */
export function quizStanding(quiz) {
  const best = quiz.me?.best;
  if (!best) return m("span", {
    className: "GauntletCard-standing"
  });
  return m("span", {
    className: 'GauntletCard-standing' + (best.passed ? ' is-passed' : '')
  }, m(Icon, {
    name: best.passed ? 'fas fa-circle-check' : 'far fa-circle'
  }), t('best', {
    score: percent(best.percent)
  }));
}

/**
 * What the reader can do next: log in, start, resume, try again, or why not.
 * With `onplay` the quiz is played in place; without, the button goes to its page.
 */
export function quizAction(quiz, onplay) {
  const me = quiz.me;
  if (!app.session.user) {
    return quiz.isOpen ? m(Button, {
      className: "Button",
      onclick: () => app.modal.show(() => flarum.reg.asyncModuleImport('flarum/forum/components/LogInModal'))
    }, t('log_in')) : null;
  }
  if (!quiz.canTake) {
    return m("span", {
      className: "GauntletCard-note"
    }, t(quiz.isOpen ? 'cannot_take' : 'closed'));
  }
  if (me && me.attemptsLeft === 0 && !me.openAttemptId && !quiz.canEdit) {
    return m("span", {
      className: "GauntletCard-note"
    }, t('no_attempts'));
  }
  const label = me?.openAttemptId ? 'resume' : me?.best ? 'again' : quiz.canEdit && quiz.status === 'draft' ? 'preview' : 'start';
  return onplay ? m(Button, {
    className: "Button Button--primary",
    icon: "fas fa-play",
    onclick: onplay
  }, t(label)) : m(Link, {
    className: "Button Button--primary",
    href: quizUrl(quiz)
  }, t(label));
}

/** Keep a quiz's own standing in step with a finished attempt, without asking the server again. */
export function recordFinish(quiz, result) {
  if (!quiz.me || result.practice) return;
  const best = quiz.me.best;
  quiz.attemptCount++;
  if (result.passed && !best?.passed) quiz.passCount++;
  quiz.me.openAttemptId = null;
  quiz.me.attemptsUsed = result.attemptsUsed;
  quiz.me.attemptsLeft = result.attemptsLeft;
  if (!best || result.percent > best.percent || result.percent === best.percent && result.duration < best.duration) {
    quiz.me.best = {
      attemptId: result.id,
      percent: result.percent,
      duration: result.duration,
      passed: result.passed || !!best?.passed
    };
  } else if (result.passed) {
    best.passed = true;
  }
}
flarum.reg.add('ernestdefoe-gauntlet', 'forum/components/QuizActions', { quizStanding: quizStanding,quizAction: quizAction,recordFinish: recordFinish, });